/* @lc app=leetcode id=3933 lang=kotlin */ class Solution { fun cnt(P: Array<IntArray>, n: Int, m: Int, r1: Int, r2: Int, c1: Int, c2: Int): Int = maxOf(0, r1).let { a -> minOf(n - 1, r2).let { b -> maxOf(0, c1).let { c -> minOf(m - 1, c2).let { d -> if (a > b || c > d) 0 else P[b + 1][d + 1] - P[a][d + 1] - P[b + 1][c] + P[a][c] } } } } fun countLocalMaximums(matrix: Array<IntArray>): Int = matrix.size.let { n -> matrix[0].size.let { m -> Array(201) { t -> Array(n + 1) { IntArray(m + 1) }.also { P -> (0 until n).forEach { i -> (0 until m).forEach { j -> P[i + 1][j + 1] = P[i][j + 1] + P[i + 1][j] - P[i][j] + (if (matrix[i][j] > t) 1 else 0) } } } }.let { PS -> (0 until n).sumOf { i -> (0 until m).count { j -> matrix[i][j].let { x -> x > 0 && cnt(PS[x], n, m, i - x + 1, i + x - 1, j - x, j + x) + cnt(PS[x], n, m, i - x, i + x, j - x + 1, j + x - 1) == 0 } } } } } } }